+#[derive(Clone)]
+struct HighlightSpecParser;
+
+impl TypedValueParser for HighlightSpecParser {
+    type Value = CustomHighlight;
+
+    fn parse_ref(
+        &self,
+        _cmd: &clap::Command,
+        _arg: Option<&Arg>,
+        value: &OsStr,
+    ) -> Result<Self::Value, clap::Error> {
+        let raw = value
+            .to_str()
+            .ok_or_else(|| clap::Error::raw(clap::error::ErrorKind::InvalidUtf8, "invalid utf-8"))?;
+
+        let (color_name, words_raw) = raw.split_once(':').ok_or_else(|| {
+            clap::Error::raw(
+                clap::error::ErrorKind::ValueValidation,
+                format!("Expected format COLOR:word1,word2,... found `{raw}`"),
+            )
+        })?;
+
+        let color = HighlightColor::parse(color_name).map_err(|message| {
+            clap::Error::raw(clap::error::ErrorKind::ValueValidation, message)
+        })?;
+
+        let words = words_raw
+            .split(',')
+            .map(ToOwned::to_owned)
+            .collect::<Vec<_>>();
+        let active = !words.is_empty() && words.iter().all(|word| !word.is_empty());
+
+        Ok(CustomHighlight { color, words, active })
+    }
+
