+    )]
+    pager: Option<String>,
+
+    #[arg(value_name = "FILE", help = "Filepath")]
+    file: Option<PathBuf>,
+}
+
+#[derive(Clone)]
+struct HighlightOptions {
+    groups: Vec<HighlightGroup>,
+    custom: Vec<CustomHighlight>,
+    builtin_keywords: bool,
+}
+
+impl HighlightOptions {
+    fn group_enabled(&self, group: HighlightGroup) -> bool {
+        self.groups.contains(&group)
+    }
+}
+
+enum AppError {
+    Cross(String),
+    Warning(String),
+}
+
+impl AppError {
+    fn cross(message: impl Into<String>) -> Self {
+        Self::Cross(message.into())
+    }
+
+    fn warning(message: impl Into<String>) -> Self {
+        Self::Warning(message.into())
+    }
+
+    fn print(&self) {
+        match self {
+            Self::Cross(message) => eprintln!("Error:   × {message}"),
+            Self::Warning(message) => eprintln!("Error:   ⚠ {message}"),
