+fn try_render_info(text: &str, index: usize, options: &HighlightOptions) -> Option<(usize, String)> {
+    if !options.builtin_keywords {
+        return None;
+    }
+
+    match_word(text, index, "INFO").map(|end| (end, style("37", "INFO")))
+}
+
+fn try_render_number(
+    text: &str,
+    index: usize,
+    options: &HighlightOptions,
+) -> Option<(usize, String)> {
+    if !options.group_enabled(HighlightGroup::Numbers) || !is_left_boundary(text, index) {
+        return None;
+    }
+
+    let mut cursor = index;
+    let mut saw_digit = false;
+    while let Some(ch) = text[cursor..].chars().next() {
+        if ch.is_ascii_digit() {
+            saw_digit = true;
+            cursor += ch.len_utf8();
+        } else {
+            break;
+        }
+        if cursor >= text.len() {
+            break;
+        }
+    }
+
+    if !saw_digit {
+        return None;
+    }
+
+    if text[cursor..].starts_with('.') {
+        let dot = cursor;
+        cursor += 1;
+        let mut frac_digits = 0;
+        while let Some(ch) = text[cursor..].chars().next() {
+            if ch.is_ascii_digit() {
+                frac_digits += 1;
+                cursor += ch.len_utf8();
+            } else {
+                break;
+            }
+            if cursor >= text.len() {
+                break;
+            }
+        }
+        if frac_digits == 0 {
+            cursor = dot;
+        }
+    }
+
+    if !is_right_boundary(text, cursor) {
+        return None;
+    }
+
+    Some((cursor, style("36", &text[index..cursor])))
+}
+
+fn parse_named_date(text: &str, index: usize) -> Option<(usize, String)> {
+    let slice = &text[index..];
+    for weekday in WEEKDAYS {
+        let prefix = format!("{weekday} ");
+        if let Some(rest) = slice.strip_prefix(&prefix) {
+            for month in MONTHS {
+                let month_prefix = format!("{month} ");
+                if let Some(rest) = rest.strip_prefix(&month_prefix) {
+                    let (day, after_day) = take_exact_digits(rest, 2)?;
+                    let rest = after_day.strip_prefix(' ')?;
+                    let (time_end, time_rendered) = parse_time_at(rest)?;
+                    let end = index + prefix.len() + month_prefix.len() + 2 + 1 + time_end;
+                    return Some((
+                        end,
+                        format!(
+                            "{prefix}{month_prefix}{}{}{}",
+                            style("36", day),
+                            style("31", " "),
+                            time_rendered
+                        ),
+                    ));
+                }
+            }
+        }
+    }
+
+    for month in MONTHS {
+        let prefix = format!("{month} ");
+        if let Some(rest) = slice.strip_prefix(&prefix) {
+            let (day, after_day) = take_exact_digits(rest, 2)?;
+            let rest = after_day.strip_prefix(' ')?;
+            let (time_end, time_rendered) = parse_time_at(rest)?;
+            let end = index + prefix.len() + 2 + 1 + time_end;
+            return Some((
+                end,
+                format!(
+                    "{prefix}{}{}{}",
+                    style("36", day),
+                    style("31", " "),
+                    time_rendered
+                ),
+            ));
+        }
+    }
+
+    None
+}
+
+fn parse_year_date(text: &str, index: usize) -> Option<(usize, String)> {
+    let slice = &text[index..];
+    let separator = slice.as_bytes().get(4).copied()? as char;
+    if separator != '-' && separator != '/' {
+        return None;
+    }
+    if slice.as_bytes().get(7).copied()? as char != separator {
+        return None;
+    }
+
+    let year = &slice.get(0..4)?;
+    let month = &slice.get(5..7)?;
+    let day = &slice.get(8..10)?;
+    if !year.chars().all(|ch| ch.is_ascii_digit())
+        || !month.chars().all(|ch| ch.is_ascii_digit())
+        || !day.chars().all(|ch| ch.is_ascii_digit())
+    {
+        return None;
+    }
+
+    let mut rendered = String::new();
+    rendered.push_str(&style("35", year));
+    rendered.push_str(&style("2", &separator.to_string()));
+    rendered.push_str(&style("35", month));
+    rendered.push_str(&style("2", &separator.to_string()));
+    rendered.push_str(&style("35", day));
+
+    let mut end = index + 10;
+    if let Some(joiner) = slice.get(10..11) {
+        if joiner == " " || joiner == "T" {
+            let (time_end, time_rendered) = parse_time_at(&slice[11..])?;
+            rendered.push_str(&style("31", joiner));
+            rendered.push_str(&time_rendered);
+            end += 1 + time_end;
+            if slice.get(11 + time_end..12 + time_end) == Some("Z") {
+                rendered.push_str(&style("31", "Z"));
+                end += 1;
+            }
+        }
+    }
+
+    Some((end, rendered))
+}
+
+fn parse_time(text: &str, index: usize) -> Option<(usize, String)> {
+    let slice = &text[index..];
+    let (end, rendered) = parse_time_at(slice)?;
+    Some((index + end, rendered))
+}
+
+fn parse_time_at(text: &str) -> Option<(usize, String)> {
+    let hour = text.get(0..2)?;
+    let sep1 = text.get(2..3)?;
+    let minute = text.get(3..5)?;
+    let sep2 = text.get(5..6)?;
+    let second = text.get(6..8)?;
+    if !hour.chars().all(|ch| ch.is_ascii_digit())
+        || !minute.chars().all(|ch| ch.is_ascii_digit())
+        || !second.chars().all(|ch| ch.is_ascii_digit())
+        || sep1 != ":"
+        || sep2 != ":"
+    {
+        return None;
+    }
+
+    let mut rendered = String::new();
+    rendered.push_str(&style("34", hour));
+    rendered.push_str(&style("2", ":"));
+    rendered.push_str(&style("34", minute));
+    rendered.push_str(&style("2", ":"));
+    rendered.push_str(&style("34", second));
+
+    let mut end = 8;
+    if let Some(separator) = text.get(8..9) {
+        if separator == "." || separator == "," || separator == ":" {
+            let mut frac_end = 9;
+            while let Some(ch) = text[frac_end..].chars().next() {
+                if ch.is_ascii_digit() {
+                    frac_end += 1;
+                } else {
+                    break;
+                }
+                if frac_end >= text.len() {
+                    break;
+                }
+            }
+            if frac_end > 9 {
+                rendered.push_str(&style("2", separator));
+                rendered.push_str(&style("34", &text[9..frac_end]));
+                end = frac_end;
+            }
+        }
+    }
+
+    Some((end, rendered))
+}
+
+fn render_null(options: &HighlightOptions) -> String {
+    if options.builtin_keywords {
+        style("3;31", "null")
+    } else {
+        "null".to_owned()
+    }
+}
+
+fn render_uuid_token(token: &str) -> String {
+    let mut rendered = String::new();
+    for ch in token.chars() {
+        if ch == '-' {
+            rendered.push_str(&style("31", "-"));
+        } else {
+            rendered.push_str(&render_hex_char(ch));
+        }
+    }
+    rendered
+}
+
+fn render_ip_token(token: &str) -> String {
+    let mut rendered = String::new();
+    for ch in token.chars() {
+        if ch == ':' || ch == '.' {
+            rendered.push_str(&style("31", &ch.to_string()));
+        } else if ch.is_ascii_digit() {
+            rendered.push_str(&style("3;34", &ch.to_string()));
+        } else {
+            rendered.push_str(&style("3;35", &ch.to_string()));
+        }
+    }
+    rendered
+}
+
+fn render_path_token(token: &str) -> String {
+    let mut rendered = String::new();
+    for ch in token.chars() {
+        match ch {
+            '/' => rendered.push_str(&style("33", "/")),
+            '~' => rendered.push_str(&style("32", "~")),
+            _ => rendered.push_str(&style("32", &ch.to_string())),
+        }
+    }
+    rendered
+}
+
+fn render_hex_char(ch: char) -> String {
+    if ch.is_ascii_digit() {
+        style("3;34", &ch.to_string())
+    } else {
+        style("3;35", &ch.to_string())
+    }
+}
+
+fn style(code: &str, text: &str) -> String {
+    format!("\x1b[{code}m{text}{RESET}")
+}
+
+fn match_word(text: &str, index: usize, word: &str) -> Option<usize> {
+    text[index..]
+        .starts_with(word)
+        .then_some(index + word.len())
+        .filter(|end| is_left_boundary(text, index) && is_right_boundary(text, *end))
+}
+
+fn match_custom_word(text: &str, index: usize, word: &str) -> Option<usize> {
+    text[index..]
+        .starts_with(word)
+        .then_some(index + word.len())
+        .filter(|end| is_left_boundary(text, index) && is_right_boundary(text, *end))
+}
+
+fn is_left_boundary(text: &str, index: usize) -> bool {
+    if index == 0 {
+        return true;
+    }
+    text[..index]
+        .chars()
+        .last()
+        .map(|ch| !is_word_char(ch))
+        .unwrap_or(true)
+}
+
+fn is_right_boundary(text: &str, index: usize) -> bool {
+    if index >= text.len() {
+        return true;
+    }
+    text[index..]
+        .chars()
+        .next()
+        .map(|ch| !is_word_char(ch))
+        .unwrap_or(true)
+}
+
+fn is_right_hex_boundary(text: &str, index: usize) -> bool {
+    if index >= text.len() {
+        return true;
+    }
+    !text[index..]
+        .chars()
+        .next()
+        .map(|ch| ch.is_ascii_hexdigit())
+        .unwrap_or(false)
+}
