#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum HighlightColor {
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
}

impl HighlightColor {
    fn parse(name: &str) -> Result<Self, String> {
        match name {
            "red" => Ok(Self::Red),
            "green" => Ok(Self::Green),
            "yellow" => Ok(Self::Yellow),
            "blue" => Ok(Self::Blue),
            "magenta" => Ok(Self::Magenta),
            "cyan" => Ok(Self::Cyan),
            _ => Err(format!("invalid variant: {name}")),
        }
    }

    fn code(self) -> &'static str {
        match self {
            Self::Red => "31",
            Self::Green => "32",
            Self::Yellow => "33",
            Self::Blue => "34",
            Self::Magenta => "35",
            Self::Cyan => "36",
        }
    }
}

#[derive(Clone)]
struct HighlightSpecParser;

impl TypedValueParser for HighlightSpecParser {
    type Value = CustomHighlight;

    fn parse_ref(
        &self,
        _cmd: &clap::Command,
        _arg: Option<&Arg>,
        value: &OsStr,
    ) -> Result<Self::Value, clap::Error> {
        let raw = value
            .to_str()
            .ok_or_else(|| clap::Error::raw(clap::error::ErrorKind::InvalidUtf8, "invalid utf-8"))?;

        let (color_name, words_raw) = raw.split_once(':').ok_or_else(|| {
            clap::Error::raw(
                clap::error::ErrorKind::ValueValidation,
                format!("Expected format COLOR:word1,word2,... found `{raw}`"),
            )
        })?;

        let color = HighlightColor::parse(color_name).map_err(|message| {
            clap::Error::raw(clap::error::ErrorKind::ValueValidation, message)
        })?;

        let words = words_raw
            .split(',')
            .map(ToOwned::to_owned)
            .collect::<Vec<_>>();
        let active = !words.is_empty() && words.iter().all(|word| !word.is_empty());

        Ok(CustomHighlight { color, words, active })
    }

    fn possible_values(
        &self,
    ) -> Option<Box<dyn Iterator<Item = PossibleValue> + '_>> {
        Some(Box::new(
            ["red", "green", "yellow", "blue", "magenta", "cyan"]
                .into_iter()
                .map(PossibleValue::new),
        ))
    }
}

