    }
}

enum AppError {
    Cross(String),
    Warning(String),
}

impl AppError {
    fn cross(message: impl Into<String>) -> Self {
        Self::Cross(message.into())
    }

    fn warning(message: impl Into<String>) -> Self {
        Self::Warning(message.into())
    }

    fn print(&self) {
        match self {
            Self::Cross(message) => eprintln!("Error:   × {message}"),
            Self::Warning(message) => eprintln!("Error:   ⚠ {message}"),
        }
    }
}

fn main() {
    let mut command = Args::command();
    if let Some(bin_name) = env::args().next().and_then(|arg| {
        Path::new(&arg)
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
    }) {
        command = command.bin_name(bin_name);
    }

    let matches = match command.try_get_matches() {
        Ok(matches) => matches,
        Err(error) => error.exit(),
    };

    let args = match Args::from_arg_matches(&matches) {
        Ok(args) => args,
        Err(error) => error.exit(),
    };

    if let Err(error) = run(args) {
        error.print();
        std::process::exit(1);
    }
}

fn run(args: Args) -> Result<(), AppError> {
    load_config(args.config_path.as_deref())?;

    if !args.enable.is_empty() && !args.disable.is_empty() {
        return Err(AppError::cross(
            "cannot both enable and disable highlighters",
        ));
    }

    if args.file.is_some() && args.exec.is_some() {
        return Err(AppError::cross(format!(
            "Cannot read from both file and {}",
            style("35", "--listen-command")
        )));
    }

    let stdin_is_terminal = io::stdin().is_terminal();
    let print_mode = args.print || (!stdin_is_terminal && args.file.is_none() && args.exec.is_none());

    let groups = if args.enable.is_empty() {
        let mut groups = vec![
            HighlightGroup::Numbers,
            HighlightGroup::Urls,
            HighlightGroup::Pointers,
            HighlightGroup::Dates,
            HighlightGroup::Paths,
            HighlightGroup::Quotes,
            HighlightGroup::KeyValuePairs,
            HighlightGroup::Uuids,
            HighlightGroup::IpAddresses,
            HighlightGroup::Processes,
            HighlightGroup::Json,
        ];
        groups.retain(|group| !args.disable.contains(group));
        groups
    } else {
        args.enable.clone()
    };

    let options = HighlightOptions {
        groups,
        custom: args.highlights.clone(),
        builtin_keywords: !args.disable_builtin_keywords,
    };

    match (&args.file, &args.exec) {
        (Some(path), None) => run_file(path, args.follow, print_mode, args.pager.as_deref(), &options),
        (None, Some(command)) => run_exec(command, print_mode, args.pager.as_deref(), &options),
        (None, None) => {
            if stdin_is_terminal {
                return Ok(());
            }
            let mut input = String::new();
            io::stdin()
                .read_to_string(&mut input)
                .map_err(|error| AppError::cross(error.to_string()))?;
            print!("{}", highlight_text(&input, &options));
            io::stdout()
                .flush()
                .map_err(|error| AppError::cross(error.to_string()))
        }
        _ => unreachable!(),
    }
}

fn load_config(explicit_path: Option<&Path>) -> Result<(), AppError> {
    let path = match explicit_path {
        Some(path) => Some(path.to_path_buf()),
        None => default_config_path(),
    };

    let Some(path) = path else {
        return Ok(());
    };

    if !path.exists() {
        if explicit_path.is_some() {
            return Err(AppError::cross("could not find the TOML file"));
        }
        return Ok(());
    }

    let content = fs::read_to_string(&path)
        .map_err(|error| AppError::cross(error.to_string()))?;
    content
        .parse::<toml::Value>()
        .map_err(|error| AppError::cross(error.to_string()))?;
    Ok(())
}

fn default_config_path() -> Option<PathBuf> {
    if let Ok(xdg) = env::var("XDG_CONFIG_HOME") {
        let path = Path::new(&xdg).join("tailspin").join("theme.toml");
        if path.exists() {
            return Some(path);
        }
    }

    env::var("HOME")
        .ok()
        .map(|home| Path::new(&home).join(".config").join("tailspin").join("theme.toml"))
        .filter(|path| path.exists())
}

fn run_file(
    path: &Path,
    follow: bool,
    print_mode: bool,
    pager: Option<&str>,
    options: &HighlightOptions,
) -> Result<(), AppError> {
    if !path.exists() {
        return Err(AppError::warning(format!(
            "{}: No such file or directory",
            style("33", &path.display().to_string())
        )));
    }

    if follow && print_mode {
        return follow_file(path, options);
    }

    let content = fs::read_to_string(path).map_err(|error| AppError::cross(error.to_string()))?;
    let rendered = highlight_text(&content, options);

    if print_mode {
        print!("{rendered}");
        io::stdout()
            .flush()
            .map_err(|error| AppError::cross(error.to_string()))?;
        return Ok(());
    }

    page_output(&rendered, pager)
}

fn follow_file(path: &Path, options: &HighlightOptions) -> Result<(), AppError> {
    let mut file = File::open(path).map_err(|error| AppError::cross(error.to_string()))?;
    let mut position = 0_u64;

    loop {
        file.seek(SeekFrom::Start(position))
            .map_err(|error| AppError::cross(error.to_string()))?;
        let mut chunk = String::new();
        file.read_to_string(&mut chunk)
            .map_err(|error| AppError::cross(error.to_string()))?;
        if !chunk.is_empty() {
            position += chunk.as_bytes().len() as u64;
            print!("{}", highlight_text(&chunk, options));
            io::stdout()
                .flush()
                .map_err(|error| AppError::cross(error.to_string()))?;
        }

        let metadata = fs::metadata(path).map_err(|error| AppError::cross(error.to_string()))?;
        if metadata.len() < position {
            file = File::open(path).map_err(|error| AppError::cross(error.to_string()))?;
            position = 0;
        }

        thread::sleep(Duration::from_millis(100));
    }
}

fn run_exec(
    command: &str,
    print_mode: bool,
    pager: Option<&str>,
    options: &HighlightOptions,
) -> Result<(), AppError> {
    let output = Command::new("sh")
        .arg("-c")
        .arg(command)
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .output()
        .map_err(|error| AppError::cross(error.to_string()))?;

    let stdout = String::from_utf8_lossy(&output.stdout);
    let rendered = highlight_text(&stdout, options);

    if print_mode {
        print!("{rendered}");
        io::stdout()
            .flush()
            .map_err(|error| AppError::cross(error.to_string()))?;
        return Ok(());
    }

    page_output(&rendered, pager)
}

fn page_output(rendered: &str, pager: Option<&str>) -> Result<(), AppError> {
    let mut file = NamedTempFile::new().map_err(|error| AppError::cross(error.to_string()))?;
    file.write_all(rendered.as_bytes())
        .map_err(|error| AppError::cross(error.to_string()))?;
    file.flush()
        .map_err(|error| AppError::cross(error.to_string()))?;

    let pager = pager.unwrap_or("less -R [FILE]");
    let path = file.path().to_string_lossy().to_string();
    let (program, args) = parse_pager_command(pager, &path)?;

    Command::new(program)
        .args(args)
        .status()
        .map_err(|error| AppError::cross(error.to_string()))?;

    Ok(())
}

fn parse_pager_command(command: &str, file_path: &str) -> Result<(String, Vec<String>), AppError> {
    if !command.contains("[FILE]") {
        return Err(AppError::cross("Could not parse custom pager command"));
    }

    let expanded = command.replace("[FILE]", file_path);
    let parts = shell_words::split(&expanded)
        .map_err(|_| AppError::cross("Could not parse custom pager command"))?;
    if parts.is_empty() {
        return Err(AppError::cross("Could not parse custom pager command"));
    }

    Ok((parts[0].clone(), parts[1..].to_vec()))
}

fn highlight_text(input: &str, options: &HighlightOptions) -> String {
    let mut output = String::new();
    let mut start = 0;

    for (index, ch) in input.char_indices() {
        if ch == '\n' {
            output.push_str(&highlight_line(&input[start..index], options));
            output.push('\n');
            start = index + 1;
        }
    }

    if start < input.len() {
        output.push_str(&highlight_line(&input[start..], options));
    }

    output
}

fn highlight_line(line: &str, options: &HighlightOptions) -> String {
    if options.group_enabled(HighlightGroup::Json) {
        let trimmed = line.trim();
        if !trimmed.is_empty() {
            if let Ok(value) = serde_json::from_str::<Value>(trimmed) {
                return render_json(&value, options);
            }
        }
    }

    render_plain_text(line, options)
}

fn render_json(value: &Value, options: &HighlightOptions) -> String {
    match value {
        Value::Null => render_null(options),
        Value::Bool(value) => {
            if options.builtin_keywords {
                style("3;31", if *value { "true" } else { "false" })
            } else if *value {
                "true".to_owned()
            } else {
                "false".to_owned()
            }
        }
        Value::Number(number) => {
            let text = number.to_string();
            if options.group_enabled(HighlightGroup::Numbers) {
                style("36", &text)
            } else {
                text
            }
        }
        Value::String(text) => {
            let inner = render_plain_text_without_quotes(text, options);
            format!("{}{}{}", style("2", "\""), inner, style("2", "\""))
        }
        Value::Array(items) => {
            let mut rendered = String::new();
            rendered.push_str(&style("2", "["));
            for (index, item) in items.iter().enumerate() {
                if index > 0 {
                    rendered.push_str(&style("2", ","));
                    rendered.push(' ');
                }
                rendered.push_str(&render_json(item, options));
            }
            rendered.push_str(&style("2", "]"));
            rendered
        }
        Value::Object(map) => {
            let mut rendered = String::new();
            rendered.push_str(&style("2", "{"));
            rendered.push(' ');
            for (index, (key, value)) in map.iter().enumerate() {
                if index > 0 {
                    rendered.push_str(&style("2", ","));
                    rendered.push(' ');
                }
                rendered.push_str(&style("2", "\""));
                rendered.push_str(&style("2", key));
                rendered.push_str(&style("2", "\""));
                rendered.push_str(&style("2", ":"));
                rendered.push(' ');
                rendered.push_str(&render_json(value, options));
            }
            rendered.push(' ');
            rendered.push_str(&style("2", "}"));
            rendered
        }
    }
}

fn render_plain_text_without_quotes(text: &str, options: &HighlightOptions) -> String {
    let mut no_quotes = options.clone();
    no_quotes.groups.retain(|group| *group != HighlightGroup::Quotes && *group != HighlightGroup::Json);
    render_plain_text(text, &no_quotes)
}

fn render_plain_text(text: &str, options: &HighlightOptions) -> String {
    let mut output = String::new();
    let mut index = 0;

    while index < text.len() {
        if let Some((end, rendered)) = try_render_key_value(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_url(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_process(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_pointer(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_uuid(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_ip(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_date(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_path(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_quote(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_rest_method(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_boolean_or_null(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_severity(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_custom(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_info(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }
        if let Some((end, rendered)) = try_render_number(text, index, options) {
            output.push_str(&rendered);
            index = end;
            continue;
        }

        let ch = text[index..].chars().next().unwrap();
        output.push(ch);
        index += ch.len_utf8();
    }

    output
}

fn try_render_key_value(
    text: &str,
    index: usize,
    options: &HighlightOptions,
) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::KeyValuePairs) || !is_left_boundary(text, index) {
        return None;
    }

    let mut cursor = index;
    while let Some(ch) = text[cursor..].chars().next() {
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
            cursor += ch.len_utf8();
        } else {
            break;
        }
        if cursor >= text.len() {
            break;
        }
    }

    if cursor == index || text.as_bytes().get(cursor) != Some(&b'=') {
        return None;
    }

    let key = &text[index..cursor];
    let value_start = cursor + 1;
    let value_end = if text[value_start..].starts_with('"') {
        match find_closing_quote(text, value_start) {
            Some(end) => end + 1,
            None => return None,
        }
    } else {
        let mut end = value_start;
        while let Some(ch) = text[end..].chars().next() {
            if ch.is_whitespace() {
                break;
            }
            end += ch.len_utf8();
            if end >= text.len() {
                break;
            }
        }
        end
    };

    let value = &text[value_start..value_end];
    Some((
        value_end,
        format!(
            "{}{}{}",
            style("2", key),
            style("37", "="),
            render_plain_text(value, options)
        ),
    ))
}

fn try_render_url(text: &str, index: usize, options: &HighlightOptions) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::Urls) || !is_left_boundary(text, index) {
        return None;
    }

    let slice = &text[index..];
    let matched = URL_RE.find(slice)?;
    if matched.start() != 0 {
        return None;
    }

    let token = matched.as_str();
    let scheme_end = token.find("://")?;
    let scheme = &token[..scheme_end];
    let rest = &token[scheme_end + 3..];
    let first_split = rest.find(['/', '?']).unwrap_or(rest.len());
    let host = &rest[..first_split];
    let remainder = &rest[first_split..];
    let path_end = remainder.find('?').unwrap_or(remainder.len());
    let path = &remainder[..path_end];
    let query = &remainder[path_end..];

    let scheme_code = if scheme == "https" { "2;32" } else { "2;31" };
    let mut rendered = String::new();
    rendered.push_str(&style(scheme_code, scheme));
    rendered.push_str("://");
    rendered.push_str(&style("2;34", host));
    rendered.push_str(&style("34", path));

    if let Some(query) = query.strip_prefix('?') {
        rendered.push_str(&style("31", "?"));
        for (index, part) in query.split('&').enumerate() {
            if index > 0 {
                rendered.push_str(&style("31", "&"));
            }
            if let Some((key, value)) = part.split_once('=') {
                rendered.push_str(&style("35", key));
                rendered.push_str(&style("31", "="));
                rendered.push_str(&style("36", value));
            } else {
                rendered.push_str(&style("35", part));
            }
        }
    }

    Some((index + token.len(), rendered))
}

fn try_render_process(
    text: &str,
    index: usize,
    options: &HighlightOptions,
) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::Processes) || !is_left_boundary(text, index) {
        return None;
    }

    let mut cursor = index;
    while let Some(ch) = text[cursor..].chars().next() {
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
            cursor += ch.len_utf8();
        } else {
            break;
        }
        if cursor >= text.len() {
            break;
        }
    }

    if cursor == index || text.as_bytes().get(cursor) != Some(&b'[') {
        return None;
    }

    let pid_start = cursor + 1;
    let mut pid_end = pid_start;
    while let Some(ch) = text[pid_end..].chars().next() {
        if ch.is_ascii_digit() {
            pid_end += ch.len_utf8();
        } else {
            break;
        }
        if pid_end >= text.len() {
            break;
        }
    }

    if pid_end == pid_start {
        return None;
    }
    if text.as_bytes().get(pid_end) != Some(&b']') || text.as_bytes().get(pid_end + 1) != Some(&b':') {
        return None;
    }

    let name = &text[index..cursor];
    let pid = &text[pid_start..pid_end];
    Some((
        pid_end + 2,
        format!(
            "{}{}{}{}:",
            style("33", name),
            style("31", "["),
            style("36", pid),
            style("31", "]")
        ),
    ))
}

fn try_render_pointer(
    text: &str,
    index: usize,
    options: &HighlightOptions,
) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::Pointers) || !is_left_boundary(text, index) {
        return None;
    }

    let slice = &text[index..];
    let lower = slice.as_bytes();
    if lower.len() < 10 || lower[0] != b'0' || lower[1] != b'x' {
        return None;
    }

    let length = if lower.len() >= 18 && lower[2..18].iter().all(|byte| byte.is_ascii_hexdigit()) {
        if is_right_hex_boundary(text, index + 18) {
            16
        } else {
            0
        }
    } else if lower[2..10].iter().all(|byte| byte.is_ascii_hexdigit()) && is_right_hex_boundary(text, index + 10) {
        8
    } else {
        0
    };

    if length == 0 {
        return None;
    }

    let digits = &slice[2..2 + length];
    let mut rendered = String::new();
    rendered.push_str(&style("3;34", "0"));
    rendered.push_str(&style("31", "x"));
    for (position, ch) in digits.chars().enumerate() {
        if length == 16 && position == 8 {
            rendered.push_str(&style("2", "•"));
        }
        rendered.push_str(&render_hex_char(ch));
    }

    Some((index + 2 + length, rendered))
}

fn try_render_uuid(text: &str, index: usize, options: &HighlightOptions) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::Uuids) || !is_left_boundary(text, index) {
        return None;
    }

    let slice = &text[index..];
    let matched = UUID_RE.find(slice)?;
    if matched.start() != 0 || !is_right_boundary(text, index + matched.end()) {
        return None;
    }

    let token = matched.as_str();
    Some((index + token.len(), render_uuid_token(token)))
}

fn try_render_ip(text: &str, index: usize, options: &HighlightOptions) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::IpAddresses) || !is_left_boundary(text, index) {
        return None;
    }

    let end = ip_candidate_end(text, index);
    if end == index {
        return None;
    }

    let token = &text[index..end];

    if let Some((address, port)) = token
        .strip_prefix('[')
        .and_then(|rest| rest.split_once("]:"))
    {
        if !port.is_empty()
            && port.chars().all(|ch| ch.is_ascii_digit())
            && looks_like_highlightable_ip(address)
            && address.parse::<std::net::IpAddr>().is_ok()
        {
            return Some((
                end,
                format!(
                    "[{}]:{}",
                    render_ip_token(address),
                    style("36", port)
                ),
            ));
        }
    }

    if let Some((address, zone)) = token.split_once('%') {
        if looks_like_highlightable_ip(address) && address.parse::<std::net::IpAddr>().is_ok() {
            return Some((end, format!("{}%{}", render_ip_token(address), zone)));
        }
    }

    if looks_like_highlightable_ip(token) && token.parse::<std::net::IpAddr>().is_ok() {
        return Some((end, render_ip_token(token)));
    }

    None
}

fn try_render_date(text: &str, index: usize, options: &HighlightOptions) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::Dates) || !is_left_boundary(text, index) {
        return None;
    }

    parse_named_date(text, index)
        .or_else(|| parse_year_date(text, index))
        .or_else(|| parse_time(text, index))
}

fn try_render_path(text: &str, index: usize, options: &HighlightOptions) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::Paths) {
        return None;
    }

    let starts_with_tilde = text[index..].starts_with("~/");
    let starts_with_root = text[index..].starts_with('/');
    if !starts_with_tilde && !starts_with_root {
        return None;
    }
    if starts_with_root && !is_left_boundary(text, index) {
        return None;
    }
    if starts_with_tilde && !is_left_boundary(text, index) {
        return None;
    }

    let mut cursor = index;
    let mut segments = 0_u32;
    let mut trailing_slash = false;

    if starts_with_tilde {
        cursor += 2;
        segments = 1;
        trailing_slash = true;
    } else {
        cursor += 1;
        trailing_slash = true;
    }

    while cursor < text.len() {
        let next = text[cursor..].chars().next().unwrap();
        if is_path_stop(next) {
            break;
        }
        if next == '/' {
            trailing_slash = true;
            cursor += 1;
            continue;
        }
        trailing_slash = false;
        cursor += next.len_utf8();
        if text[cursor - next.len_utf8()..cursor].chars().all(|ch| ch != '/') {
            let previous = if cursor == index + 1 {
                '/'
            } else {
                text[..cursor - next.len_utf8()].chars().last().unwrap_or(' ')
            };
            if previous == '/' {
                segments += 1;
            }
        }
    }

    let min_segments = if starts_with_tilde { 2 } else { 2 };
    if segments < min_segments || trailing_slash {
        return None;
    }

    let token = &text[index..cursor];
    Some((cursor, render_path_token(token)))
}

fn try_render_quote(text: &str, index: usize, options: &HighlightOptions) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::Quotes) || !text[index..].starts_with('"') {
        return None;
    }

    let end = find_closing_quote(text, index)?;
    let inner = &text[index + 1..end];
    let rendered_inner = render_plain_text_without_quotes(inner, options);
    let rendered = if rendered_inner == inner {
        style("33", &text[index..end + 1])
    } else {
        format!("\"{}\"", rendered_inner)
    };

    Some((end + 1, rendered))
}

fn try_render_rest_method(
    text: &str,
    index: usize,
    options: &HighlightOptions,
) -> Option<(usize, String)> {
    if !options.builtin_keywords {
        return None;
    }

    let methods = [
        ("DELETE", "41;30"),
        ("PATCH", "45;30"),
        ("POST", "43;30"),
        ("PUT", "45;30"),
        ("GET", "42;30"),
    ];

    for (word, color) in methods {
        if let Some(end) = match_word(text, index, word) {
            return Some((end, style(color, &format!(" {word} "))));
        }
    }

    None
}

fn try_render_boolean_or_null(
    text: &str,
    index: usize,
    options: &HighlightOptions,
) -> Option<(usize, String)> {
    if !options.builtin_keywords {
        return None;
    }

    for word in ["true", "false", "null"] {
        if let Some(end) = match_word(text, index, word) {
            return Some((end, style("3;31", word)));
        }
    }

    None
}

fn try_render_severity(
    text: &str,
    index: usize,
    options: &HighlightOptions,
) -> Option<(usize, String)> {
    if !options.builtin_keywords {
        return None;
    }

    let severities = [
        ("ERROR", "31"),
        ("WARN", "33"),
        ("DEBUG", "32"),
        ("TRACE", "2"),
    ];

    for (word, color) in severities {
        if let Some(end) = match_word(text, index, word) {
            return Some((end, style(color, word)));
        }
    }

    None
}

fn try_render_custom(
    text: &str,
    index: usize,
    options: &HighlightOptions,
) -> Option<(usize, String)> {
    for highlight in &options.custom {
        if !highlight.active {
            continue;
        }
        for word in &highlight.words {
            if word.is_empty() {
                continue;
            }
            if let Some(end) = match_custom_word(text, index, word) {
                return Some((end, style(highlight.color.code(), word)));
            }
        }
    }
    None
}

fn try_render_info(text: &str, index: usize, options: &HighlightOptions) -> Option<(usize, String)> {
    if !options.builtin_keywords {
        return None;
    }

    match_word(text, index, "INFO").map(|end| (end, style("37", "INFO")))
}

fn try_render_number(
    text: &str,
    index: usize,
    options: &HighlightOptions,
) -> Option<(usize, String)> {
    if !options.group_enabled(HighlightGroup::Numbers) || !is_left_boundary(text, index) {
        return None;
    }

    let mut cursor = index;
    let mut saw_digit = false;
    while let Some(ch) = text[cursor..].chars().next() {
        if ch.is_ascii_digit() {
            saw_digit = true;
            cursor += ch.len_utf8();
        } else {
            break;
        }
        if cursor >= text.len() {
            break;
        }
    }

    if !saw_digit {
        return None;
    }

    if text[cursor..].starts_with('.') {
        let dot = cursor;
        cursor += 1;
        let mut frac_digits = 0;
        while let Some(ch) = text[cursor..].chars().next() {
            if ch.is_ascii_digit() {
                frac_digits += 1;
                cursor += ch.len_utf8();
            } else {
                break;
            }
            if cursor >= text.len() {
                break;
            }
        }
        if frac_digits == 0 {
            cursor = dot;
        }
    }

    if !is_right_boundary(text, cursor) {
        return None;
    }

    Some((cursor, style("36", &text[index..cursor])))
}

fn parse_named_date(text: &str, index: usize) -> Option<(usize, String)> {
    let slice = &text[index..];
    for weekday in WEEKDAYS {
        let prefix = format!("{weekday} ");
        if let Some(rest) = slice.strip_prefix(&prefix) {
            for month in MONTHS {
                let month_prefix = format!("{month} ");
                if let Some(rest) = rest.strip_prefix(&month_prefix) {
                    let (day, after_day) = take_exact_digits(rest, 2)?;
                    let rest = after_day.strip_prefix(' ')?;
                    let (time_end, time_rendered) = parse_time_at(rest)?;
                    let end = index + prefix.len() + month_prefix.len() + 2 + 1 + time_end;
                    return Some((
                        end,
                        format!(
                            "{prefix}{month_prefix}{}{}{}",
                            style("36", day),
                            style("31", " "),
                            time_rendered
                        ),
                    ));
                }
            }
        }
    }

    for month in MONTHS {
        let prefix = format!("{month} ");
        if let Some(rest) = slice.strip_prefix(&prefix) {
            let (day, after_day) = take_exact_digits(rest, 2)?;
            let rest = after_day.strip_prefix(' ')?;
            let (time_end, time_rendered) = parse_time_at(rest)?;
            let end = index + prefix.len() + 2 + 1 + time_end;
            return Some((
                end,
                format!(
                    "{prefix}{}{}{}",
                    style("36", day),
                    style("31", " "),
                    time_rendered
                ),
            ));
        }
    }

    None
}

fn parse_year_date(text: &str, index: usize) -> Option<(usize, String)> {
    let slice = &text[index..];
    let separator = slice.as_bytes().get(4).copied()? as char;
    if separator != '-' && separator != '/' {
        return None;
    }
    if slice.as_bytes().get(7).copied()? as char != separator {
        return None;
    }

    let year = &slice.get(0..4)?;
    let month = &slice.get(5..7)?;
    let day = &slice.get(8..10)?;
    if !year.chars().all(|ch| ch.is_ascii_digit())
        || !month.chars().all(|ch| ch.is_ascii_digit())
        || !day.chars().all(|ch| ch.is_ascii_digit())
    {
        return None;
    }

    let mut rendered = String::new();
    rendered.push_str(&style("35", year));
    rendered.push_str(&style("2", &separator.to_string()));
    rendered.push_str(&style("35", month));
    rendered.push_str(&style("2", &separator.to_string()));
    rendered.push_str(&style("35", day));

    let mut end = index + 10;
    if let Some(joiner) = slice.get(10..11) {
        if joiner == " " || joiner == "T" {
            let (time_end, time_rendered) = parse_time_at(&slice[11..])?;
            rendered.push_str(&style("31", joiner));
            rendered.push_str(&time_rendered);
            end += 1 + time_end;
            if slice.get(11 + time_end..12 + time_end) == Some("Z") {
                rendered.push_str(&style("31", "Z"));
                end += 1;
            }
        }
    }

    Some((end, rendered))
}

fn parse_time(text: &str, index: usize) -> Option<(usize, String)> {
    let slice = &text[index..];
    let (end, rendered) = parse_time_at(slice)?;
    Some((index + end, rendered))
}

fn parse_time_at(text: &str) -> Option<(usize, String)> {
    let hour = text.get(0..2)?;
    let sep1 = text.get(2..3)?;
    let minute = text.get(3..5)?;
    let sep2 = text.get(5..6)?;
    let second = text.get(6..8)?;
    if !hour.chars().all(|ch| ch.is_ascii_digit())
        || !minute.chars().all(|ch| ch.is_ascii_digit())
        || !second.chars().all(|ch| ch.is_ascii_digit())
        || sep1 != ":"
        || sep2 != ":"
    {
        return None;
    }

    let mut rendered = String::new();
    rendered.push_str(&style("34", hour));
    rendered.push_str(&style("2", ":"));
    rendered.push_str(&style("34", minute));
    rendered.push_str(&style("2", ":"));
    rendered.push_str(&style("34", second));

    let mut end = 8;
    if let Some(separator) = text.get(8..9) {
        if separator == "." || separator == "," || separator == ":" {
            let mut frac_end = 9;
            while let Some(ch) = text[frac_end..].chars().next() {
                if ch.is_ascii_digit() {
                    frac_end += 1;
                } else {
                    break;
                }
                if frac_end >= text.len() {
                    break;
                }
            }
            if frac_end > 9 {
                rendered.push_str(&style("2", separator));
                rendered.push_str(&style("34", &text[9..frac_end]));
                end = frac_end;
            }
        }
    }

    Some((end, rendered))
}

fn render_null(options: &HighlightOptions) -> String {
    if options.builtin_keywords {
        style("3;31", "null")
    } else {
        "null".to_owned()
    }
}

fn render_uuid_token(token: &str) -> String {
    let mut rendered = String::new();
    for ch in token.chars() {
        if ch == '-' {
            rendered.push_str(&style("31", "-"));
        } else {
            rendered.push_str(&render_hex_char(ch));
        }
    }
    rendered
}

fn render_ip_token(token: &str) -> String {
    let mut rendered = String::new();
    for ch in token.chars() {
        if ch == ':' || ch == '.' {
            rendered.push_str(&style("31", &ch.to_string()));
        } else if ch.is_ascii_digit() {
            rendered.push_str(&style("3;34", &ch.to_string()));
        } else {
            rendered.push_str(&style("3;35", &ch.to_string()));
        }
    }
    rendered
}

fn render_path_token(token: &str) -> String {
    let mut rendered = String::new();
    for ch in token.chars() {
        match ch {
            '/' => rendered.push_str(&style("33", "/")),
            '~' => rendered.push_str(&style("32", "~")),
            _ => rendered.push_str(&style("32", &ch.to_string())),
        }
    }
    rendered
}

fn render_hex_char(ch: char) -> String {
    if ch.is_ascii_digit() {
        style("3;34", &ch.to_string())
    } else {
        style("3;35", &ch.to_string())
    }
}

fn style(code: &str, text: &str) -> String {
    format!("\x1b[{code}m{text}{RESET}")
}

fn match_word(text: &str, index: usize, word: &str) -> Option<usize> {
    text[index..]
        .starts_with(word)
        .then_some(index + word.len())
        .filter(|end| is_left_boundary(text, index) && is_right_boundary(text, *end))
}

fn match_custom_word(text: &str, index: usize, word: &str) -> Option<usize> {
    text[index..]
        .starts_with(word)
        .then_some(index + word.len())
        .filter(|end| is_left_boundary(text, index) && is_right_boundary(text, *end))
}

fn is_left_boundary(text: &str, index: usize) -> bool {
    if index == 0 {
        return true;
    }
    text[..index]
        .chars()
        .last()
        .map(|ch| !is_word_char(ch))
        .unwrap_or(true)
}

fn is_right_boundary(text: &str, index: usize) -> bool {
    if index >= text.len() {
        return true;
    }
    text[index..]
        .chars()
        .next()
        .map(|ch| !is_word_char(ch))
        .unwrap_or(true)
}

fn is_right_hex_boundary(text: &str, index: usize) -> bool {
    if index >= text.len() {
        return true;
    }
    !text[index..]
        .chars()
        .next()
        .map(|ch| ch.is_ascii_hexdigit())
        .unwrap_or(false)
}

fn is_word_char(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || ch == '_'
}

fn is_path_stop(ch: char) -> bool {
    ch.is_whitespace()
        || matches!(ch, '"' | '\'' | ',' | ')' | ']' | '}' | ':' | ';')
}

fn find_closing_quote(text: &str, start: usize) -> Option<usize> {
    let mut index = start + 1;
    while index < text.len() {
        let ch = text[index..].chars().next()?;
        if ch == '"' {
            return Some(index);
        }
        index += ch.len_utf8();
    }
    None
}

fn take_exact_digits(text: &str, count: usize) -> Option<(&str, &str)> {
    let digits = text.get(..count)?;
    if digits.chars().all(|ch| ch.is_ascii_digit()) {
        Some((digits, &text[count..]))
    } else {
        None
    }
}

fn ip_candidate_end(text: &str, index: usize) -> usize {
    let mut end = index;
    while end < text.len() {
        let ch = text[end..].chars().next().unwrap();
        if ch.is_ascii_alphanumeric() || matches!(ch, '.' | ':' | '[' | ']' | '%') {
            end += ch.len_utf8();
        } else {
            break;
        }
    }
    end
}

fn looks_like_highlightable_ip(token: &str) -> bool {
    token.chars().any(|ch| ch.is_ascii_hexdigit()) && (token.contains('.') || token.contains(':'))
}
